import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
  selector: 'app-establishment',
  templateUrl: './establishment.page.html',
  styleUrls: ['./establishment.page.scss'],
})
export class EstablishmentPage implements OnInit {
 
  class = [
    {label: "UKG",value: 1 },
    {label: "I",value: 2 },
    {label: "II",value: 3 },
    {label: "III",value: 4 },
  ]
  routeData: any;
  status: any;
  uidse: any;
  onAgency: boolean;
  onAgency1: boolean;
  onAgencyData: boolean;

  constructor(
    private route: ActivatedRoute,
    private router: Router) { }

  ngOnInit() {
  }
 
  ionViewDidEnter() {
    this.routeData = this.route.snapshot;
    this.status = this.routeData.queryParams.status;
    this.uidse = this.routeData.queryParams.uidse;
  }

  goToBack() {
    this.router.navigate(['/tabs/regulator-section'], {
      queryParams: { status: 1, "uidse": this.uidse }, skipLocationChange: false
    });
  }

  onSave() {
    this.router.navigate(['/tabs/regulator-section'], {
      queryParams: { status: 1, "uidse": this.uidse }, skipLocationChange: false
    });
 
  
  }

  onOfChange(event,id){
    if(id == 2){
      this.onAgency = false;
    }
    if(id == 1 ){
      this.onAgency = true;
    }
  }
  
    onOfChange1(event,id){
      if(id == 2 ){
        this.onAgency1 = false;
      }
      if(id == 1 ){
        this.onAgency1 = true;
      }
    }
  
}
